input.command:
cd /tmp; NOW=$(date +%s); mkdir -p /tmp/zw/T/ka /tmp/zw/T/kb /tmp/zw/T/kc /tmp/zw/T/zz
mk(){ rm -rf /tmp/zw/$1; mkdir -p /tmp/zw/$1; }
gen(){ printf '%s\t%s\t%s\n' /tmp/zw/T/ka 9 $NOW /tmp/zw/T/kb 5 $NOW /tmp/zw/T/kc 1 $NOW /tmp/zw/T/zz 7 $NOW | python3 /tmp/zw/mkdb.py /tmp/zw/$1/db.zo 2>/dev/null; }
mk P1; gen P1; echo "### non-list query k with glob k[bc]"; _ZO_DATA_DIR=/tmp/zw/P1 _ZO_EXCLUDE_DIRS='/tmp/zw/T/k[bc]' /workspace/executable query k; python3 /tmp/zw/rddb.py /tmp/zw/P1/db.zo | tail -n +2
mk P2; gen P2; echo "### --list query k with glob k[bc]"; _ZO_DATA_DIR=/tmp/zw/P2 _ZO_EXCLUDE_DIRS='/tmp/zw/T/k[bc]' /workspace/executable query --list k; python3 /tmp/zw/rddb.py /tmp/zw/P2/db.zo | tail -n +2
mk P3; gen P3; echo "### --list query k, glob matches zz (non-keyword)"; _ZO_DATA_DIR=/tmp/zw/P3 _ZO_EXCLUDE_DIRS='/tmp/zw/T/zz' /workspace/executable query --list k; python3 /tmp/zw/rddb.py /tmp/zw/P3/db.zo | tail -n +2

cd /tmp; NOW=$(date +%s); mk(){ rm -rf /tmp/zw/$1; mkdir -p /tmp/zw/$1; }
mk Q1; printf '%s\t1\t%s\n' /tmp/zw/T/foo $NOW /tmp/zw/T/a/foo $NOW | python3 /tmp/zw/mkdb.py /tmp/zw/Q1/db.zo
echo "### base-dir /tmp/zw/T/a + glob on /tmp/zw/T/foo (outside base)"; _ZO_DATA_DIR=/tmp/zw/Q1 _ZO_EXCLUDE_DIRS='/tmp/zw/T/foo' /workspace/executable query --list --base-dir /tmp/zw/T/a foo; python3 /tmp/zw/rddb.py /tmp/zw/Q1/db.zo | tail -n +2
mk Q2; printf '%s\t1\t%s\n' '/tmp/zw/T/foo/' $NOW 'T/foo' $NOW './rel/foo' $NOW '' $NOW 'foo' $NOW | python3 /tmp/zw/mkdb.py /tmp/zw/Q2/db.zo
echo "### odd stored paths, query foo (cwd=/tmp/zw)"; (cd /tmp/zw && mkdir -p rel/foo && _ZO_DATA_DIR=/tmp/zw/Q2 /workspace/executable query --list --all foo)
echo "### query 'foo/'"; _ZO_DATA_DIR=/tmp/zw/Q2 /workspace/executable query --list --all 'foo/'
echo "### exists check for relative stored path from cwd=/tmp/zw"; (cd /tmp/zw && _ZO_DATA_DIR=/tmp/zw/Q2 /workspace/executable query --list foo)
echo "### exists check from cwd=/"; (cd / && _ZO_DATA_DIR=/tmp/zw/Q2 /workspace/executable query --list foo)

content.content:
function __zoxide_pwd() {
    \builtin pwd -L
}
__zoxide_z_prefix='z#'
function __zoxide_zi() {
    __zoxide_doctor
    \builtin local result
    result="$(\command zoxide query --interactive -- "$@")" && __zoxide_cd "${result}"
}
